1	// How the MHPCO settles a claim against a policy: what the policy covers in
2	// total, and what it will pay out. This is settlement policy, separate from
3	// the premium policy that decides what the office charges.
4	
5	import { ClaimOfficeRefusal } from "./claim-office-refusal.js";
6	import { type Item, insuranceValue } from "./item-catalogue.js";
7	
8	const CAP_MULTIPLE = 2;
9	const DEDUCTIBLE = 100;
10	const REDUCED_REIMBURSEMENT_ENCHANTMENT = 8;
11	const REDUCED_REIMBURSEMENT_RATE = 0.5;
12	
13	// The insurance sum is the sum of the insured items' insurance values; the
14	// block discount affects the premium only, never the insurance sum.
15	export function insuranceSum(items: Item[]): number {
16	  return items.reduce((total, item) => total + insuranceValue(item), 0);
17	}
18	
19	// The total payout per policy is capped at twice the insurance sum.
20	export function policyCap(items: Item[]): number {
21	  return insuranceSum(items) * CAP_MULTIPLE;
22	}
23	
24	export interface Damage {
25	  itemType: string;
26	  amount: number;
27	}
28	
29	export interface Settlement {
30	  payout: number;
31	  remainingCap: number;
32	}
33	
34	// Damage to an item enchanted at this level or above is reimbursed at half.
35	function isReducedReimbursement(item: Item): boolean {
36	  return (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT;
37	}
38	
39	// The reimbursement clauses decide what a damage is worth before the
40	// deductible is withheld. Dragon material is fully reimbursed, which is also
41	// the default for an item no clause reduces, so it needs no separate branch:
42	// where dragon material meets high enchantment the spec's examples give the
43	// 50 % rule precedence (dragon sword, enchantment 8 or 9, damage 1000 G ->
44	// payout 400 G).
45	function reimbursableAmount(item: Item, damage: Damage): number {
46	  return isReducedReimbursement(item)
47	    ? damage.amount * REDUCED_REIMBURSEMENT_RATE
48	    : damage.amount;
49	}
50	
51	// A deductible is withheld per damage event, after the reimbursement clauses
52	// have decided what the damage is worth.
53	function damagePayout(item: Item, damage: Damage): number {
54	  return reimbursableAmount(item, damage) - DEDUCTIBLE;
55	}
56	
57	// Which covered item a reported damage refers to. A damage report names only
58	// an item type, so the office has to match it against what the policy actually
59	// covers -- and refuses the claim outright when the policy covers no such item.
60	function coveredItemFor(items: Item[], damage: Damage): Item {
61	  const covered = items.find((item) => item.type === damage.itemType);
62	  if (covered === undefined) {
63	    throw new ClaimOfficeRefusal(
64	      `the policy does not cover an item of type ${damage.itemType}`,
65	    );
66	  }
67	  return covered;
68	}
69	
70	// Every damage in an incident is settled on its own -- two damaged swords are
71	// two damage events, each bearing its own deductible -- and the claim pays out
72	// the sum of them.
73	function claimPayout(items: Item[], damages: Damage[]): number {
74	  return damages.reduce(
75	    (total, damage) =>
76	      total + damagePayout(coveredItemFor(items, damage), damage),
77	    0,
78	  );
79	}
80	
81	// The total payout per policy is capped, so the office never pays more than
82	// the cap the policy has left: a claim that wants more is reduced to it.
83	function payoutWithinRemainingCap(
84	  desiredPayout: number,
85	  remainingCap: number,
86	): number {
87	  return Math.min(desiredPayout, remainingCap);
88	}
89	
90	// Amounts are rounded to whole G in the MHPCO's favour: a payout is rounded
91	// down. Intermediate amounts are kept as fractions.
92	function roundPayoutInMhpcoFavor(payout: number): number {
93	  return Math.floor(payout);
94	}
95	
96	// Settling a claim: what the incident is worth, reduced to what the policy's
97	// cap still permits, and what that leaves of the cap for later claims.
98	export function settleClaim(
99	  items: Item[],
100	  damages: Damage[],
101	  remainingCap: number,
102	): Settlement {
103	  const desiredPayout = claimPayout(items, damages);
104	  const permittedPayout = payoutWithinRemainingCap(desiredPayout, remainingCap);
105	  const payout = roundPayoutInMhpcoFavor(permittedPayout);
106	  return { payout, remainingCap: remainingCap - payout };
107	}
