1	import {
2	  COMPONENT_BASE_PREMIUM,
3	  isComponent,
4	  listedBasePremium,
5	  mainItemBasePremium,
6	  type Item,
7	} from "./item-catalogue.js";
8	
9	export type { Item };
10	
11	export interface Customer {
12	  yearsWithMHPCO: number;
13	}
14	
15	const PROCESSING_FEE = 5;
16	
17	const BLOCK_SIZE = 3;
18	const BLOCK_BASE_PREMIUM = 60;
19	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
20	const LOYALTY_YEARS = 2;
21	const LOYALTY_DISCOUNT_RATE = 0.2;
22	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
23	const CURSE_SURCHARGE_RATE = 0.5;
24	const HIGH_ENCHANTMENT_LEVEL = 5;
25	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
26	
27	function sum(amounts: number[]): number {
28	  return amounts.reduce((total, amount) => total + amount, 0);
29	}
30	
31	function alikeComponentsBasePremium(alikeComponents: Item[]): number {
32	  return alikeComponents.length === BLOCK_SIZE
33	    ? BLOCK_BASE_PREMIUM
34	    : alikeComponents.length * COMPONENT_BASE_PREMIUM;
35	}
36	
37	// "Alike" components are components of exactly the same type, not merely of
38	// the same family; only alike components can form a building block.
39	function alikeKey(component: Item): string {
40	  return component.type;
41	}
42	
43	function groupAlikeComponents(components: Item[]): Item[][] {
44	  const groups = new Map<string, Item[]>();
45	  for (const component of components) {
46	    const key = alikeKey(component);
47	    const group = groups.get(key) ?? [];
48	    group.push(component);
49	    groups.set(key, group);
50	  }
51	  return [...groups.values()];
52	}
53	
54	function componentsBasePremium(components: Item[]): number {
55	  return sum(groupAlikeComponents(components).map(alikeComponentsBasePremium));
56	}
57	
58	export function policyBasePremium(items: Item[]): number {
59	  const components = items.filter(isComponent);
60	  const mainItems = items.filter((item) => !isComponent(item));
61	  return (
62	    sum(mainItems.map(mainItemBasePremium)) + componentsBasePremium(components)
63	  );
64	}
65	
66	function isCursed(item: Item): boolean {
67	  return item.cursed === true;
68	}
69	
70	function isHighlyEnchanted(item: Item): boolean {
71	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
72	}
73	
74	// An item bears every risk factor it qualifies for; a cursed, highly enchanted
75	// item therefore carries both surcharges.
76	function itemRiskSurchargeRate(item: Item): number {
77	  const curse = isCursed(item) ? CURSE_SURCHARGE_RATE : 0;
78	  const highEnchantment = isHighlyEnchanted(item)
79	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
80	    : 0;
81	  return curse + highEnchantment;
82	}
83	
84	// A surcharge is assessed on the item's own list price, deliberately not on
85	// its share of the policy base premium: the block discount is a policy pricing
86	// rule, so a rune in a block is still assessed on the full 25 G.
87	function itemRiskSurcharge(item: Item): number {
88	  return listedBasePremium(item) * itemRiskSurchargeRate(item);
89	}
90	
91	// Item-specific modifiers apply to the base premium of the affected item.
92	function itemRiskSurcharges(items: Item[]): number {
93	  return sum(items.map(itemRiskSurcharge));
94	}
95	
96	// The customer's standing with MHPCO, as far as the premium is concerned.
97	interface CustomerStanding {
98	  customer: Customer;
99	  previousContracts: number;
100	}
101	
102	// Every item in a quote is treated as a first insurance, regardless of the
103	// customer's history, so this surcharge does not depend on the customer.
104	function firstInsuranceSurcharge(basePremium: number): number {
105	  return basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
106	}
107	
108	function isLongStanding({ customer }: CustomerStanding): boolean {
109	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
110	}
111	
112	function loyaltyDiscount(
113	  standing: CustomerStanding,
114	  basePremium: number,
115	): number {
116	  return isLongStanding(standing) ? basePremium * LOYALTY_DISCOUNT_RATE : 0;
117	}
118	
119	// Every contract after the customer's first is a follow-up contract.
120	function isFollowUpContract({ previousContracts }: CustomerStanding): boolean {
121	  return previousContracts > 0;
122	}
123	
124	function followUpContractDiscount(
125	  standing: CustomerStanding,
126	  basePremium: number,
127	): number {
128	  return isFollowUpContract(standing)
129	    ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE
130	    : 0;
131	}
132	
133	// Policy-wide modifiers (first insurance, loyalty, follow-up contract) all
134	// apply to the policy base premium. Returns the net adjustment: surcharges
135	// positive, discounts negative. Each modifier is applied to the base premium
136	// separately rather than as a summed rate, so that intermediate amounts match
137	// the per-modifier figures in the MHPCO's own worked examples.
138	function policyWideModifiers(
139	  standing: CustomerStanding,
140	  basePremium: number,
141	): number {
142	  return (
143	    firstInsuranceSurcharge(basePremium) -
144	    loyaltyDiscount(standing, basePremium) -
145	    followUpContractDiscount(standing, basePremium)
146	  );
147	}
148	
149	// All amounts are rounded to whole G in the MHPCO's favour. For a premium --
150	// money flowing to MHPCO -- its favour is upwards. A payout rounds the other
151	// way, and settlement policy owns that direction itself: the shared principle
152	// is "never to MHPCO's disadvantage", but the direction is a fact about this
153	// kind of amount, so each side keeps its own. Intermediate amounts are kept as
154	// fractions; only the final premium is rounded.
155	function roundPremiumInMhpcoFavor(premium: number): number {
156	  return Math.ceil(premium);
157	}
158	
159	// The premium the MHPCO assesses for the policy itself: the policy base
160	// premium adjusted by the item-specific and policy-wide modifiers. The
161	// processing fee is not part of the assessment; it is added at the very end.
162	function assessedPremium(standing: CustomerStanding, items: Item[]): number {
163	  const basePremium = policyBasePremium(items);
164	  return (
165	    basePremium +
166	    itemRiskSurcharges(items) +
167	    policyWideModifiers(standing, basePremium)
168	  );
169	}
170	
171	export function quote(
172	  customer: Customer,
173	  items: Item[],
174	  previousContracts = 0,
175	): number {
176	  const standing = { customer, previousContracts };
177	  return roundPremiumInMhpcoFavor(
178	    assessedPremium(standing, items) + PROCESSING_FEE,
179	  );
180	}
