1	// The MHPCO price list: which items the office insures at all, and what each
2	// one is worth to it. This is catalogue knowledge, not pricing policy -- it
3	// changes when the office revises its tariffs or takes on a new kind of item,
4	// independently of how premiums or payouts are assessed from it.
5	
6	import { ClaimOfficeRefusal } from "./claim-office-refusal.js";
7	
8	export interface Item {
9	  type: string;
10	  material?: string;
11	  enchantment?: number;
12	  cursed?: boolean;
13	}
14	
15	const MAIN_ITEM_INSURANCE_VALUES: Record<string, number> = {
16	  sword: 1000,
17	  amulet: 600,
18	  staff: 800,
19	  potion: 400,
20	};
21	
22	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	};
28	
29	// Components -- for example runes and moonstones -- share a single list price.
30	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
31	export const COMPONENT_BASE_PREMIUM = 25;
32	const COMPONENT_INSURANCE_VALUE = 250;
33	
34	// The office insures only the items in its catalogue; anything else is
35	// refused rather than priced.
36	function isInsurable(item: Item): boolean {
37	  return isComponent(item) || item.type in MAIN_ITEM_BASE_PREMIUMS;
38	}
39	
40	export function isComponent(item: Item): boolean {
41	  return COMPONENT_TYPES.has(item.type);
42	}
43	
44	// The office will not quote a policy over an item it does not insure; it
45	// refuses the scenario and names every offending type.
46	export function refuseUninsurableItems(items: Item[]): void {
47	  const uninsurable = items.filter((item) => !isInsurable(item));
48	  if (uninsurable.length > 0) {
49	    throw new ClaimOfficeRefusal(
50	      `the MHPCO does not insure items of type: ${uninsurable
51	        .map((item) => item.type)
52	        .join(", ")}`,
53	    );
54	  }
55	}
56	
57	export function mainItemBasePremium(item: Item): number {
58	  return MAIN_ITEM_BASE_PREMIUMS[item.type];
59	}
60	
61	// An item's own list price, whatever kind of item it is.
62	export function listedBasePremium(item: Item): number {
63	  return isComponent(item) ? COMPONENT_BASE_PREMIUM : mainItemBasePremium(item);
64	}
65	
66	// What the office insures an item for, independently of what it charges.
67	export function insuranceValue(item: Item): number {
68	  return isComponent(item)
69	    ? COMPONENT_INSURANCE_VALUE
70	    : MAIN_ITEM_INSURANCE_VALUES[item.type];
71	}
