1	// The register of policies a scenario has opened. It knows two things the
2	// office would otherwise have to remember by hand: how a later claim addresses
3	// an earlier policy -- by the zero-based index of the quote step that opened
4	// it -- and how much of each policy's cap is left once claims have been settled
5	// against it, since the cap is a per-policy total carried across claims.
6	
7	import { type Damage, type Settlement, policyCap, settleClaim } from "./claim-settlement.js";
8	import { type Item } from "./item-catalogue.js";
9	
10	// A policy, once quoted, carries its items and whatever cap it has left.
11	interface Policy {
12	  items: Item[];
13	  remainingCap: number;
14	}
15	
16	export class PolicyRegister {
17	  private readonly policies = new Map<number, Policy>();
18	
19	  // A quote opens a policy over its items, with the full cap still available.
20	  open(reference: number, items: Item[]): void {
21	    this.policies.set(reference, { items, remainingCap: policyCap(items) });
22	  }
23	
24	  // Settling against a registered policy draws on the cap it has left, so what
25	  // this claim does not exhaust remains available to the next one.
26	  settleAgainst(reference: number, damages: Damage[]): Settlement {
27	    const policy = this.policies.get(reference) as Policy;
28	    const settlement = settleClaim(policy.items, damages, policy.remainingCap);
29	    policy.remainingCap = settlement.remainingCap;
30	    return settlement;
31	  }
32	}
