1	// Running a scenario: the MHPCO processes a customer's steps in order, so a
2	// quote creates a policy that a later claim can be made against.
3	
4	import { type Customer, quote } from "./claim-office.js";
5	import { type Damage } from "./claim-settlement.js";
6	import { type Item, refuseUninsurableItems } from "./item-catalogue.js";
7	import { PolicyRegister } from "./policy-register.js";
8	
9	export interface QuoteStep {
10	  op: "quote";
11	  items: Item[];
12	}
13	
14	export interface ClaimStep {
15	  op: "claim";
16	  policy: number;
17	  incident: { cause: string; damages: Damage[] };
18	}
19	
20	export type Step = QuoteStep | ClaimStep;
21	
22	export interface Scenario {
23	  customer: Customer;
24	  steps: Step[];
25	}
26	
27	export interface QuoteResult {
28	  premium: number;
29	}
30	
31	export interface ClaimResult {
32	  payout: number;
33	  remainingCap: number;
34	}
35	
36	export type StepResult = QuoteResult | ClaimResult;
37	
38	export function runScenario(scenario: Scenario): StepResult[] {
39	  const policies = new PolicyRegister();
40	  // Every quote in the scenario closes a contract, so each later quote is a
41	  // follow-up contract for this customer.
42	  let previousContracts = 0;
43	
44	  function runQuote(step: QuoteStep, reference: number): QuoteResult {
45	    refuseUninsurableItems(step.items);
46	    const premium = quote(scenario.customer, step.items, previousContracts);
47	    previousContracts += 1;
48	    policies.open(reference, step.items);
49	    return { premium };
50	  }
51	
52	  function runClaim(step: ClaimStep): ClaimResult {
53	    return policies.settleAgainst(step.policy, step.incident.damages);
54	  }
55	
56	  return scenario.steps.map((step, index) =>
57	    step.op === "quote" ? runQuote(step, index) : runClaim(step),
58	  );
59	}
