1	#!/usr/bin/env node
2	// The claim-office command: reads a scenario as JSON on stdin and writes the
3	// corresponding results as JSON on stdout. Transport only -- every decision
4	// belongs to the domain modules it calls.
5	
6	import { ClaimOfficeRefusal } from "./claim-office-refusal.js";
7	import { type Scenario, runScenario } from "./scenario.js";
8	
9	async function readStdin(): Promise<string> {
10	  const chunks: Buffer[] = [];
11	  for await (const chunk of process.stdin) {
12	    chunks.push(Buffer.from(chunk));
13	  }
14	  return Buffer.concat(chunks).toString("utf8");
15	}
16	
17	const REFUSAL_EXIT_CODE = 1;
18	
19	// A refused scenario produces no results: the office reports why on stderr
20	// and exits non-zero.
21	async function main(): Promise<void> {
22	  const scenario = JSON.parse(await readStdin()) as Scenario;
23	  try {
24	    const results = runScenario(scenario);
25	    process.stdout.write(`${JSON.stringify({ results })}\n`);
26	  } catch (error) {
27	    if (!(error instanceof ClaimOfficeRefusal)) {
28	      throw error;
29	    }
30	    process.stderr.write(`${error.message}\n`);
31	    process.exitCode = REFUSAL_EXIT_CODE;
32	  }
33	}
34	
35	await main();
